#include "event_log.hpp"

#include <cassert>
#include <iostream>

int main() {
    EventLog log(100);
    for (int i = 0; i < 5; i++) {
        log.record(Event{i, "orders", "o" + std::to_string(i)});
    }
    for (int i = 0; i < 3; i++) {
        log.record(Event{100 + i, "payments", "p" + std::to_string(i)});
    }

    int total = 0;
    auto page1 = log.historyPage(true, "orders", 1, 2, &total);
    assert(total == 5);
    assert(page1.size() == 2);
    for (const auto& e : page1) assert(e.topic == "orders");

    int total3 = 0;
    auto page3 = log.historyPage(true, "orders", 3, 2, &total3);
    assert(page3.size() == 1);

    int totalBad = 0;
    auto bad = log.historyPage(false, "", 0, 2, &totalBad);
    assert(bad.empty());
    assert(totalBad == 0);

    std::cout << "PASS" << std::endl;
    return 0;
}

