#include <algorithm>
#include <cstddef>
#include <string>
#include <vector>

#include "event.hpp"

class EventLog {
public:
    explicit EventLog(size_t capacity) : capacity_(capacity) {}

    void record(const Event& event) {
        if (entries_.size() >= capacity_) {
            entries_.erase(entries_.begin());
        }
        entries_.push_back(event);
    }

    std::vector<Event> history() const { return entries_; }

    size_t size() const { return entries_.size(); }

    /*
     * Returns a page of history entries, optionally filtered by topic,
     * with pagination applied AFTER the filter. `outTotal` receives the
     * count of ALL matching entries (not just the page). `page` is
     * 1-based; both `page` and `pageSize` must be >= 1 or an empty
     * vector is returned with `outTotal` set to 0.
     */
    std::vector<Event> historyPage(bool hasFilter, const std::string& topicFilter,
                                   int page, int pageSize, int* outTotal) const {
        *outTotal = static_cast<int>(entries_.size());
        if (page < 1 || pageSize < 1) {
            *outTotal = 0;
            return {};
        }
        int start = (page - 1) * pageSize;
        if (start >= static_cast<int>(entries_.size())) {
            return {};
        }
        int end = std::min(start + pageSize, static_cast<int>(entries_.size()));
        std::vector<Event> pageSlice(entries_.begin() + start, entries_.begin() + end);
        if (!hasFilter) {
            return pageSlice;
        }
        std::vector<Event> filtered;
        for (const auto& e : pageSlice) {
            if (e.topic == topicFilter) {
                filtered.push_back(e);
            }
        }
        return filtered;
    }

private:
    std::vector<Event> entries_;
    size_t capacity_;
};
